#!/usr/bin/env bash
# ==============================================================================
# Garuda v1.8 — Deterministic Build-Context Receipts, Polyglot Reproducibility,
#               CI-vs-Editor Drift Detector & Cross-Platform Matrix Installer
# ==============================================================================
set -e

REPO_DIR="${1:-$HOME/garuda}"
echo "🦅 Upgrading Garuda workspace at ${REPO_DIR} to v1.8 (Build-Context Receipts & Cross-Platform Reproducibility)..."
mkdir -p "${REPO_DIR}"
cd "${REPO_DIR}"

# Cleanly exit any paused git state and remove leftover demo violation scratch files
git rebase --abort 2>/dev/null || true
git merge --abort 2>/dev/null || true
rm -rf internal/api/bad_violation.go garuda_video_build
git rm -f --cached internal/api/bad_violation.go 2>/dev/null || true
git rm -rf --cached garuda_video_build 2>/dev/null || true

echo "📦 Extracting embedded v1.8 source update..."
base64 -d << 'GARUDA_V18_EOF' | tar -xzf -
