GARUDA_V18_EOF

echo "🔨 Building all 4 pure-Go binaries (CGO_ENABLED=0)..."
mkdir -p bin
CGO_ENABLED=0 go build -v -o bin/garuda ./cmd/garuda
CGO_ENABLED=0 go build -v -o bin/garuda-api ./cmd/garuda-api
CGO_ENABLED=0 go build -v -o bin/garuda-mcp ./cmd/garuda-mcp
CGO_ENABLED=0 go build -v -o bin/garuda-talon ./cmd/garuda-talon

echo "🧪 Running Build-Context & Conditional Edge unit tests (TestTwoBuildsExposeDifferentEdges)..."
CGO_ENABLED=0 go test -v -run TestTwoBuildsExposeDifferentEdges ./internal/analyzer/...
CGO_ENABLED=0 go test -v ./internal/merkle/... ./internal/policy/... ./internal/diff/...

echo "🧭 Testing Cross-Platform Build Matrix & Build-Context Receipt..."
./bin/garuda check --matrix --workspace default || true

echo "✅ Garuda v1.8 upgrade complete!"
